-- *POSTPONED Camas: Sacred Food of the Nimiipuu POSTPONED*
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = '*POSTPONED Camas: Sacred Food of the Nimiipuu POSTPONED*' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('*POSTPONED Camas: Sacred Food of the Nimiipuu POSTPONED*', 'EVENT HOST HAS POSTPONED TO A LATER DATE TBD. Washington State University and University of Idaho Native American Student Center''s present CAMAS: SACRED FOOD OF THE NIMIIPUU. The film shares the historical and cultural significance of the camas plant to the Nez Perce people, featuring interviews with several members of the Nez Perce Tribe. Rated: Not Rated | 1 hr 30 min | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/8x10-Native-American-Heritage-Events-Flyer-232x300.png', 90, 'N', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2022-11-29 19:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
  SELECT v_movie_id, '2022-11-29 19:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles', 0, 200, false
  WHERE NOT EXISTS (SELECT 1 FROM public.showings WHERE movie_id = v_movie_id AND start_time = '2022-11-29 19:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles');
END $$;

