  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Absolute Anime: Angel&#8217;s Egg' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Absolute Anime: Angel&#8217;s Egg', 'Thursday, November 20 at 7 PM KPAC presents the all-new 4K restoration of ANGEL''S EGG as part of our Absolute Anime series. In an underwater city, a young girl takes care of a large egg she holds carefully in her arms – a treasure that she believes is an angel’s egg. A boy with a gun arrives in search of a bird he saw in his dream. At first it seems as if feelings of sympathy are developing between the two. Then, one night, the boy crushes her precious egg. First released directly to home video in 1985, the film is a creative collaboration between internationally acclaimed director Mamoru Oshii ( Ghost in the Shell ), who wrote and directed the feature, and revered artist Yoshitaka Amano ( Final Fantasy , Vampire Hunter D ). The film beautifully intertwines Oshii’s thematic reflections on philosophy and theology, with Amano’s distinctive ink painting style, culminating in an arrestingly beautiful hand-drawn allegorical fantasy. Japanese with English subtitles. Rated: Not Rated | 1 hr 11 min | Tickets: $8 Adult / Film Pass', 'https://www.kenworthy.org/wp-content/uploads/angels-egg-poster-web-205x300.jpg', 71, 'N', true)
    RETURNING id INTO v_movie_id;
