  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'CCUCCC and The United Church of Moscow: God &#038; Country' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('CCUCCC and The United Church of Moscow: God &#038; Country', 'Saturday, April 13 at 2 PM Community Congregational United Church of Christ and The United Church of Moscow are hosting a screening of GOD & COUNTRY . From director Dan Partland and producer Rob Reiner, GOD & COUNTRY looks at the implications of Christian Nationalism and how it distorts not only our constitutional republic, but Christianity itself. Featuring prominent Christian thought leaders, GOD & COUNTRY asks this question: What happens when a faith built on love, sacrifice, and forgiveness grows political tentacles, conflating power, money, and belief into hyper-nationalism? The screening is a community rental hosted by Community Congregational United Church of Christ and The United Church of Moscow . Rated: PG-13 | 1 hr 30 min | Tickets: $8 General Admission', 'https://www.kenworthy.org/wp-content/uploads/GC_poster_web-204x300.jpg', 90, 'PG-13', true)
    RETURNING id INTO v_movie_id;
