  WHERE NOT EXISTS (SELECT 1 FROM public.showings WHERE movie_id = v_movie_id AND start_time = '2024-07-20 19:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles');
END $$;

-- Celebration of Sound: The Dark Knight
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Celebration of Sound: The Dark Knight' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Celebration of Sound: The Dark Knight', 'Friday, July 19 at 7 PM “An epic that will leave you staggering from the theater, stunned by its scope and complexity.” — Christy Lemire KPAC presents THE DARK KNIGHT as part of our Celebration of Sound series featuring films with incredible audio to highlight our brand new sound system! When the menace known as the Joker wreaks havoc and chaos on the people of Gotham, Batman must accept one of the greatest psychological and physical tests of his ability to fight injustice. Dark, complex, and unforgettable, The Dark Knight succeeds not just as an entertaining comic book film, but as a richly thrilling crime saga. Winner of two Oscars, with the lesser-known win being Best Sound Editing, we are thrilled to showcase it on our new sound system! Rated: PG-13 | 2 hr 32 min | Tickets: $8 Adult / $5 Child / Film Pass', 'https://www.kenworthy.org/wp-content/uploads/poster-5.jpg', 152, 'PG-13', true)
    RETURNING id INTO v_movie_id;
