-- Celebration of Sound: The Song Remains the Same
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Celebration of Sound: The Song Remains the Same' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Celebration of Sound: The Song Remains the Same', 'Thursday, July 18 at 7 PM “It''s energetic, lively, raucous and catches the essence of what made Zeppelin larger than life.” — Felix Vasquez Jr., Cinema Crazed KPAC presents the Led Zeppelin concert film THE SONG REMAINS THE SAME as part of our Celebration of Sound series featuring films with incredible audio to highlight our brand new sound system! Filmed in 1973 over the course of a three-night stand at New York City''s Madison Square Garden, this concert film shows Led Zeppelin at the apogee of their hard-rocking glory. In addition to featuring such indelible hits as "Dazed and Confused," "Whole Lotta Love" and "Stairway to Heaven," the live footage is interspersed with elaborate fantasy sequences, backstage shenanigans and a glimpse of what the business side of such a large touring operation entails. Watch it on the big screen but more importantly with big sound on our brand new sound system! Rated: PG | 2 hr 17 min | Tickets: $8 Adult / $5 Child / Film Pass', 'https://www.kenworthy.org/wp-content/uploads/poster-4.jpg', 137, 'PG', true)
    RETURNING id INTO v_movie_id;
  END IF;

