  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Fundi: The Story of Ella Baker' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Fundi: The Story of Ella Baker', 'Sunday, March 26 at 2 PM FUNDI: THE STORY OF ELLA BAKER reveals the instrumental role that Ella Baker, a friend and advisor to Martin Luther King, Jr., played in shaping the American civil rights movement. The dynamic activist was affectionately known as the Fundi, a Swahili word for a person who passes skills from one generation to another. This event is presented by the Terry Buffington Foundation nonprofit organization. Talk-back with Terry Buffington will follow the film screening. Rated: Not Rated | 1 hr 3 min | Tickets: $10 General Admission', 'https://www.kenworthy.org/wp-content/uploads/MV5BYTlhZGJjNmQtZWJjMi00MzcxLWE4YTgtYTQyZTdmZGM2NDE1XkEyXkFqcGdeQXVyMjcwMDg3NzI@._V1_FMjpg_UX1000_-203x300.jpg', 63, 'N', true)
