BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Giant Palouse Earthworm presents A Wandering Path: The Story of Gilead Media' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Giant Palouse Earthworm presents A Wandering Path: The Story of Gilead Media', 'Monday, June 26 at 7:00 PM All heavy music appreciators listen up! We have a special opportunity coming up on Monday June 26 at the Kenworthy. Director Michael Dimmitt is touring his documentary on Gilead Media. If you know anything about underground metal, you have probably heard of Gilead Media and 20 Buck Spin (originally from Olympia, WA!). This documentary covers Gilead Media and their coproduction of Migration Fest with 20 Buck Spin, as well as the history of the label. If you have any interest in understanding the history of metal in the 21st century, this is a must see documentary and a rare chance to see the film in theaters! There will also be live music performed after the film by Cruel Velvet and another act who is yet TBA. Rated: Unrated | 1 hr 38 min | Tickets: $10 General Admission', 'https://www.kenworthy.org/wp-content/uploads/354187071_767713135054628_2114932161325617696_n-1-225x300.jpg', 98, 'U', true)
