  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Habib Institute for Asian Studies: Okja', 'Thursday, February 22 at 7 PM The Habib Institute for Asian Studies presents a free screening of OKJA as part of their East Asian Ecocinema Symposium. A young South Korean girl struggles to save her friend, a genetically modified giant pig, from a multinational meat producer, in director Bong Joon-ho''s ("Parasite," "Snowpiercer") whimsical look at questions of corporate greed, GMOs and environmental sustainability. Okja sees Bong Joon-ho continuing to create defiantly eclectic entertainment and still hitting more than enough of his narrative targets in the midst of a tricky tonal juggling act. Find out more about the East Asian Ecocinema Symposium by clicking here: https://www.uidaho.edu/class/hias/events/ecocinema Rated: PG-13 | 2 hr | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/okja-27x41-web-198x300.jpg', 90, 'PG-13', true)
