  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'ICPSD: 8 Billion Angels' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('ICPSD: 8 Billion Angels', 'Wednesday, April 19 at 7:00 PM The Institute for Community Partnerships and Sustainable Development presents 8 BILLION ANGELS. In this groundbreaking new documentary, the 8 BILLION ANGELS team connects all of the planet''s environmental emergencies, including climate change, with unsustainable population growth. 8 BILLION ANGELS weaves together the voices of ordinary people around the world, from Kansas and Maine to Japan and India, as they confront the growing impact of overpopulation on their lives and the health of the planet''s rivers, oceans, land and air. With compassion and honesty, the film poses the question: Do we want a world of more people with less opportunity for good health, peace and prosperity or fewer people with more of each. Rated: Not Rated | 1 hr 19 min | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/poster-web-4-202x300.jpg', 79, 'N', true)
