  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('IRL Movie Club: My Omaha', 'Sunday, October 12 at 7:30 PM KPAC and IRL Movie Club present MY OMAHA . Filmmaker Nick Beaulieu as he returns to his hometown amid Trump-era tensions and the Black Lives Matter movement. Fresh out of college, he meets activist Leo Louis II, who introduces him to Omaha’s history of resistance, including Malcolm X’s birthplace in North Omaha. Meanwhile, Nick struggles to reconnect with his pro-Trump father, Randy, recently diagnosed with stage-4 cancer. As protests erupt and the city faces crisis, Leo works to unite Omaha while Nick and Randy attempt to bridge their divide. Together, their stories paint a portrait of a city wrestling with family conflict, political discord, and the search for common ground. IRL Movie Club screenings are only $5! Join the the club for free and get notified about future events! The In Real Life (IRL) Movie Club is an in-person club where you can gather regularly, connect with your community, and explore trending topics through the lens of independent film. Rated: Not Rated | 1 hr 25 min | Tickets: $5 GA / No Film Passes', 'https://www.kenworthy.org/wp-content/uploads/my-omaha-poster-web-202x300.jpg', 85, 'N', true)
    RETURNING id INTO v_movie_id;
