-- Latah County Library District: The Librarians
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Latah County Library District: The Librarians' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Latah County Library District: The Librarians', 'Friday, October 10 Panel Discussion at 6 PM Film Screening at 7 PM The Latah County Library District presents a free screening of acclaimed documentary THE LIBRARIANS . The film will be preceded by a panel discussion of book banning and other topics in librarianship, consisting of local and out-of-county librarians. In Texas, the Krause List targets 850 books focused on race and LGBTQIA+ stories – triggering sweeping book bans across the U.S. at an unprecedented rate. As tensions escalate, librarians connect the dots from heated school and library board meetings nationwide to lay bare the underpinnings of a large-scale coordinated extremist movement fueling the censorship efforts. Despite facing harassment, threats, and laws aimed at criminalizing their work – the librarians’ rallying cry for freedom to read is a chilling cautionary tale. Hosted by Latah County Library District. Rated: Not Rated | 1 hr 32 min | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/Revised-Flyer-web-232x300.jpg', 92, 'N', true)
    RETURNING id INTO v_movie_id;
  END IF;

