-- MET Live in HD: Carmen
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'MET Live in HD: Carmen' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('MET Live in HD: Carmen', 'Saturday, January 27 at 9:55 AM Acclaimed English director Carrie Cracknell brings a vital new production of one of opera’s most enduringly powerful works, reinvigorating the classic story with a staging that moves the action to the modern day and finds at the heart of the drama issues that could not be more relevant today: gendered violence, abusive labor structures, and the desire to break through societal boundaries. Dazzling young mezzo-soprano Aigul Akhmetshina leads a powerhouse quartet of stars in the complex and volatile title role, alongside tenor Piotr Beczała as Carmen’s troubled lover Don José, soprano Angel Blue as the loyal Micaëla, and bass-baritone Kyle Ketelsen as the swaggering Escamillo. Daniele Rustioni conducts Bizet’s heart-pounding score. Sponsored by Northwest Public Broadcasting. Run Time: 225 min | Tickets: $20 Adult or $15 Student or MET Live in HD Pass', 'https://www.kenworthy.org/wp-content/uploads/Carmen-Individual-Web-Thumbnail-1000x1480-1-203x300.jpg', 90, 'NR', true)
    RETURNING id INTO v_movie_id;
  END IF;

