-- MET Live in HD: Fedora (Canceled)
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'MET Live in HD: Fedora (Canceled)' LIMIT 1;
  IF v_movie_id IS NULL THEN
