  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Moscow Film Society: Valley Girl' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Moscow Film Society: Valley Girl', 'Thursday, January 25 at 7 PM “This movie is a little treasure, a funny, sexy, appealing story of a Valley Girl''s heartbreaking decision: Should she stick with her boring jock boyfriend, or take a chance on a punk from Hollywood?” — Roger Ebert, Chicago Sun-Times Moscow Film Society presents VALLEY GIRL as part of their Her Lens series featuring female directors! Julie, a girl from the valley, meets Randy, a punk from the city. They are from different worlds and find love. Somehow they need to stay together in spite of her trendy, shallow friends. With engaging performances from its two leads (Nicolas Cage and Deborah Foreman), Valley Girl is a goofy film that both subverts and celebrates the cheerful superficiality of teen comedies. Sponsored by University of Idaho Women''s Center. Rated: R | 1 hr 39 min | Tickets: $8 Adult or Film Pass', 'https://www.kenworthy.org/wp-content/uploads/valleygirlposter-web-198x300.jpg', 99, 'R', true)
