  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('NWPB &#038; NOVA: Climate Across America', 'Thursday, April 6 at 7 PM Northwest Public Broadcasting (NWPB) has partnered with the award-winning PBS science series NOVA, a production of GBH, to produce and distribute multiplatform, climate-focused content as part of NOVA''s Climate Across America initiative. As part of the initiative, NWPB produced two videos focused on solutions-based approaches to different aspects of climate change at the community level. This event will give our local audience the chance to preview one of those videos as well as a segment from NOVA''s Weathering the Future documentary. The event will also feature a live panel discussion of the challenges and solutions portrayed in each video and provide inspiration that each of us can take away to continue making positive changes in our communities. Rated: Not Rated | 2 hr | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/NOVA-Event-Flyer-232x300.png', 90, 'N', true)
    RETURNING id INTO v_movie_id;
