DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'No Other Land' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('No Other Land', 'Sunday, March 16 at 7 PM Good Trouble and Extinction Rebellion Palouse present NO OTHER LAND, the Academy Award winner for Best Documentary. This film made by a Palestinian-Israeli collective shows the destruction of the occupied West Bank''s Masafer Yatta by Israeli soldiers and the alliance which develops between the Palestinian activist Basel and Israeli journalist Yuval. An elegantly assembled diary of the Palestinian experience, No Other Land is a harrowing document that leaves traces of hope for a better future. Sponsored by Steve Merriam, Geoff and Sue Pritchard, Stuart Tolman and Extinction Rebellion Palouse. Rated: Not Rated | 1 hr 32 min | Tickets: $8 Adult / Film Pass', 'https://www.kenworthy.org/wp-content/uploads/Web-NOL-Poster-Mar3-web-202x300.jpg', 92, 'N', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2025-03-16 19:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
  SELECT v_movie_id, '2025-03-16 19:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles', 8.0, 200, false
  WHERE NOT EXISTS (SELECT 1 FROM public.showings WHERE movie_id = v_movie_id AND start_time = '2025-03-16 19:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles');
END $$;

