-- Olympic Champion Edwin Moses
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Olympic Champion Edwin Moses' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Olympic Champion Edwin Moses', 'Sunday, February 23 at 4 PM Two time Olympic gold medalist Dr. Edwin Moses will join us in person to introduce a new documentary " Moses: 13 Steps " that addresses his unprecedented dominance in the 400m hurdles, running undefeated in all professional competition for over 10 years. Moses will speak to his academic background in physics and engineering that enabled a breakthrough in movement science within his event. He''ll also address his work leading the civil rights campaign to end the exploitation of American Olympians in the 1970s-80s. The event starts with a brief introduction, then a screening of the new film (105 minutes), followed by a guided Q&A with Dr. Moses. This event is hosted in partnership with UI CLASS and Black Studies, with major support from Idaho Humanities Council. Additional support comes from UI College of Science, Moscow Human Rights Commission, WSU Multicultural Student Services, WSU College of Arts and Letters, Tim Gresback, Kimberly Kenworthy Manaut, and Cody and Laura Moore. 1 hr 45 min | Tickets: $10 General Admission / Free for Students / No Passes', 'https://www.kenworthy.org/wp-content/uploads/edwin-moses-27x41-web-198x300.jpg', 105, 'NR', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2025-02-23 16:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
  SELECT v_movie_id, '2025-02-23 16:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles', 10.0, 200, false
  WHERE NOT EXISTS (SELECT 1 FROM public.showings WHERE movie_id = v_movie_id AND start_time = '2025-02-23 16:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles');
