-- Oppenheimer Ethics Symposium: Bad Press
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Oppenheimer Ethics Symposium: Bad Press' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Oppenheimer Ethics Symposium: Bad Press', 'Tuesday, April 9 at 6:30 PM Documentary filmmakers Rebecca Landsberry-Baker and Joe Peeler, who co-directed the award-winning film “ Bad Press ,” will be the keynote speakers for University of Idaho’s annual Oppenheimer Ethics Symposium. The film will be shown at 6:30 p.m. Tuesday, April 9, at the Kenworthy Performing Arts Centre, 508 S. Main St. in Moscow. The screening will be followed by a question-and-answer session with the filmmakers and tribal journalist Angel Ellis. Admission is free, but donations will be accepted for the Indigenous Journalists Association. The documentary focuses on Ellis’ fight to restore guarantees of freedom of the press within her tribe after the Muscogee Nation’s government repealed its landmark Free Press Act in 2018. The film premiered at the Sundance Film Festival in 2023 and won the U.S. Documentary Special Jury Award for Freedom of Expression. Rated: Not Rated | 1 hr 38 min | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/poster-web-5-202x300.jpg', 98, 'N', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2024-04-09 19:00:00
