  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Palouse DSA Bodily Autonomy Working Group: Salt of the Earth', 'Monday, September 29 at 7 PM Palouse Democratic Socialists of America Bodily Autonomy Working Group is pleased to present a screening of the 1954 socialist feminist film SALT OF THE EARTH . Based on a 1951 strike against the Empire Zinc Company, the film centers on the women who take over their husbands’ places on the picket line after the police and state threaten the zinc miners with arrest. Salt of the Earth is an important early feminist work of art and a powerful depiction of the crucial role women play in the labor struggle. We hope to see you there! For those interested in becoming involved with the Palouse DSA Bodily Autonomy Working Group, we meet on Sundays at One World Café and can be reached by email at bawg.palousedsa@gmail.com or on Instagram at @palousedsa_bodilyautonomy. Rated: Not Rated | 1 hr 34 min | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/Salt-of-the-Earth-and-Fundraiser-Flyer-232x300.png', 94, 'N', true)
    RETURNING id INTO v_movie_id;
