-- Palouse DSA: The Encampments
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Palouse DSA: The Encampments' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Palouse DSA: The Encampments', 'Saturday, August 30 at 7 PM Palouse DSA and Palouse for Palestine present a free screening of documentary THE ENCAMPMENTS . From Executive Producer Macklemore, The Encampments offers an urgent, intimate portrait of America’s student movement, ignited at Columbia University as students protested their universities’ ties to the war on Gaza. Their actions sparked a nationwide uprising, with encampments spreading across hundreds of campuses. Featuring detained activist Mahmoud Khalil, alongside professors, whistleblowers, and organizers, the film captures the deeper stakes of a historic moment that continues to reverberate across the globe. This event is taking place at our venue under a rental agreement and is not affiliated with or endorsed by Kenworthy Performing Arts Centre. Rated: Not Rated | 1 hr 21 min | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/poster-46-225x300.jpg', 81, 'N', true)
    RETURNING id INTO v_movie_id;
