  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Palouse Free Thinkers: Religulous' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Palouse Free Thinkers: Religulous', 'Tuesday, January 23 at 7 PM Palouse Free Thinkers present RELIGULOUS, a documentary that examines the role of religion in society. It''s a provocative and humorous exploration of religion and religious belief. Narrator Bill Maher travels to various religious hotspots, including Jerusalem, the Vatican, and Salt Lake City, interviewing believers from a wide range of faiths. Maher raises important questions about the impact of religion on violence, morality, and scientific progress. The documentary is both humorous and thought-provoking, offering a critical exploration of religion without being anti-religious, serving as a compelling conversation starter that is bound to ignite discussions. Rated: R | 1 hr 41 min | Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/religulous-poster-web-200x300.jpg', 101, 'R', true)
