-- Silent Film Festival: A Page of Madness (1926)
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Silent Film Festival: A Page of Madness (1926)' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Silent Film Festival: A Page of Madness (1926)', 'Thursday, September 19 at 7 PM Japanese director Teinosuke Kinugasa''s electrifying psychological drama holds the legendary distinction as being the most fascinating, perplexing madhouse movie ever made. In a major win for the Inland Northwest, KPAC will present this film exactly as it was intended for Japanese audiences in the 1920s, with a live benshi artist who narrates and provides live commentary. Internationally renowned performer Ichiro Kataoka joins us from Tokyo on a U.S. tour that includes L.A.''s Pacific Film Archive and Harvard Film. He will deliver a unique, unreplicable performance in collaboration with composer Dylan Champagne''s new score for live cello and mixed electronic music. The Second Annual Kenworthy Silent Film Festival enjoys support from Idaho Arts (ICA) , Idaho Humanities Council , and UI Habib Institute for Asian Studies , The Japan Foundation, Creative West, and National Endowment for the Arts (NEA). 1 hr 10 min | Tickets: $15 GA / $10 Students / $50 Festival Pass', 'https://www.kenworthy.org/wp-content/uploads/PAGE-OF-MADNESS-2024-POSTER-198x300.png', 70, 'NR', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2024-09-19 19:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
