-- Silent Film Festival: Faust with Invincible Czars
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Silent Film Festival: Faust with Invincible Czars' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Silent Film Festival: Faust with Invincible Czars', 'Wednesday, September 16 at 7 PM The fourth annual Kenworthy Silent Film Festival concludes with a rousing, frightening, and altogether electric production of F.W. Murnau''s FAUST (1926). KPAC is proud to welcome Texas-based musicians Invincible Czars in a return engagement after their wildly successful PHANTOM OF THE OPERA last year. The Invincible Czars’s score for Faust is mostly original material inspired by film score composers like Bernard Herrman and John Williams peppered with and cinematic metal a la Fantomas and even a little Marcos Valle -esque bossa nova. The band keeps their tradition of incorporating music from Russian classical composers, revisiting their renditions of Mussorgsy ’s Pictures at an Exhibition and A Night on Bald Mountain in particular for this soundtrack. Five players perform the score live on violin, electric guitar, clarinet, bass clarinet, flute, glockenspiel, keyboard and drums. 1 hr 45 min | Tickets: $20 Adult / $12 Student / $50 Festival Pass', 'https://www.kenworthy.org/wp-content/uploads/Faust-Sponsors-27x41-web-198x300.jpg', 105, 'NR', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- Showing: 2026-09-16 19:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
