-- Silent Film Festival: Sherlock Jr.
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Silent Film Festival: Sherlock Jr.' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Silent Film Festival: Sherlock Jr.', 'Thursday, May 25 at 7:00 PM Spencer Cuppage concludes the festival with a new piano score featuring jazz improvisation and a modern rhythm section to complement Buster Keaton''s superlative comedy, Sherlock Jr. (1924). Stony-faced Keaton stars as a movie projectionist who imagines himself a famous sleuth literally inside the movies. Sponsored by University of Idaho Department of History. (44 min) Tickets: $15 General Admission or $10 Student or $50 Series Pass', 'https://www.kenworthy.org/wp-content/uploads/sherlock-jr-27x41-2-198x300.png', 90, 'NR', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2023-05-25 19:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
