-- Silent Film Festival: The Blood of a Poet
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Silent Film Festival: The Blood of a Poet' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Silent Film Festival: The Blood of a Poet', 'Thursday, May 11 at 7:00 PM Ruby Fulton continues the series with an original score for three keyboards and other surprises that recontextualize Jean Cocteau''s surreal fantasy, The Blood of a Poet ( Le sang d''un poète 1930). The film is a puzzle box that defies easy summation: a male artist crosses a threshold into a world of memory play, symbolism, and eruptive creativity. (55 min) Tickets: $15 General Admission or $10 Student or $50 Series Pass', 'https://www.kenworthy.org/wp-content/uploads/blood-of-a-poet-27x41-2-198x300.png', 90, 'NR', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2023-05-11 19:00:00
