-- Silent Film Festival: The Cabinet of Dr. Caligari
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Silent Film Festival: The Cabinet of Dr. Caligari' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Silent Film Festival: The Cabinet of Dr. Caligari', 'Thursday, May 18 at 7:00 PM Liam Marchant leads jazz-rock band Pumice Pocket in a tightly plotted, original composition that matches every beat and canted angle of Robert Weine''s expressionist horror, The Cabinet of Dr. Caligari ( Das Cabinet des Dr. Caligari 1921). A carnival act turns deadly when a sleepwalker haunts the city at night. Sponsored by Inland North Waste. (78 min, mature audiences) Tickets: $15 General Admission or $10 Student or $50 Series Pass', 'https://www.kenworthy.org/wp-content/uploads/cabinet-of-dr-caligari-27x41-1-198x300.png', 90, 'NR', true)
    RETURNING id INTO v_movie_id;
  END IF;

