    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('The Pro-Voice Project: Our Voices, Our Choices', 'Sunday, October 15 at 7 PM The Pro-Voice Project Presents Our Voices, Our Choices: Idaho Abortion Stories. Join us for an unforgettable evening at the Kenworthy Performing Arts Centre in Moscow on October 15. The Pro-Voice Project will present Our Voices, Our Choices, a stage production of Idaho residents’ personal stories of reproductive agency. The performance will bring the subject of abortion out of the realm of shadow and illuminate the myriad ways in which this decision touches people’s lives. The stage production will be followed by a post-performance dialog—with physicians, attorneys and activists— addressing the fallout from Idaho’s punitive and restrictive abortion laws and provide audience members with tools to restore reproductive rights in our state. The show is free to the public but tickets are required. Donations to help us off-set costs are welcome and can be made here . All additional proceeds will support The Pro-Voice Project''s efforts to change the reproductive rights conversation in Idaho. Tickets: Free; Registration Required', 'https://www.kenworthy.org/wp-content/uploads/poster-1-200x300.png', 90, 'NR', true)
    RETURNING id INTO v_movie_id;
