    VALUES ('You Hurt My Feelings', 'Saturday, July 1 at 4 PM & 7 PM Sunday, July 2 at 4 PM & 7 PM Monday, July 3 at 4 PM & 7 PM “Holofcener isn’t cold or gratuitously cruel. She’s just brutally honest, which is why she’s one of the only people suited to make a truly funny movie about brutal honesty.” — Rolling Stone A novelist''s longstanding marriage is suddenly upended when she overhears her husband giving his honest reaction to her latest book. Smart, funny, and above all entertaining, YOU HURT MY FEELINGS finds writer-director Nicole Holofcener as sharply perceptive as ever. Rated: R | 1 hr 33 min | Tickets: $7 General Admission or Film Pass', 'https://www.kenworthy.org/wp-content/uploads/r71a9sTDwhJskvoE4X4WrRv4oyN-200x300.jpg', 93, 'R', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2023-07-01 16:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
  SELECT v_movie_id, '2023-07-01 16:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles', 7.0, 200, false
  WHERE NOT EXISTS (SELECT 1 FROM public.showings WHERE movie_id = v_movie_id AND start_time = '2023-07-01 16:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles');
END $$;

-- Young Washington
DO $$
DECLARE v_movie_id UUID;
BEGIN
  SELECT id INTO v_movie_id FROM public.movies WHERE title = 'Young Washington' LIMIT 1;
  IF v_movie_id IS NULL THEN
    INSERT INTO public.movies (title, description, poster_url, duration_minutes, rating, is_active)
    VALUES ('Young Washington', 'Wednesday, July 22 at 7 PM “Stirring and inspirational without being preachy, Young Washington dramatizes the lesson that a brave man’s mistakes, when faced, can lead to his greatest triumphs.” — Thelma Adams, AARP Movies for Grownups KPAC presents YOUNG WASHINGTON . A young George Washington faces war, betrayal and impossible choices that will forge a leader. Young Washington is an authentic and heartfelt portrait of America''s founding father, combining historical reverence, stirring battle sequences, and an inspiring story of perseverance and spirit with earnest conviction. Rated: PG-13 | 2 hr 1 min | Tickets: $8 Adult / Film Pass', 'https://www.kenworthy.org/wp-content/uploads/young-washington-poster-web-202x300.jpg', 121, 'PG-13', true)
    RETURNING id INTO v_movie_id;
  END IF;

  -- [PAST] Showing: 2026-07-22 19:00:00
  INSERT INTO public.showings (movie_id, start_time, ticket_price, total_seats, is_active)
  SELECT v_movie_id, '2026-07-22 19:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles', 8.0, 200, false
  WHERE NOT EXISTS (SELECT 1 FROM public.showings WHERE movie_id = v_movie_id AND start_time = '2026-07-22 19:00:00'::timestamp AT TIME ZONE 'America/Los_Angeles');
END $$;


