INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Annette Bay Pimentel | Before Music', 'Before Music explores the ways people have used the materials around them to create musical instruments. Come explore the ways nature helps people make music and try your hand at making your own instrument. Please join us for this free family-friendly event with author Annette Bay Pimentel, sponsored by BookPeople of Moscow, at the Kenworthy Performing Arts Center, 508 S Main, Moscow, Idaho, on Saturday, June 25 at 11 AM. Annette Bay Pimentel writes about the people and ideas that shape our world from her home in Moscow, Idaho. http://www.annettebaypimentel. com/', NULL, 'ticketed', true
