INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Backstage Music: Mars Child', 'Saturday, April 26 at 10:30 PM Get down to some Americana-Doom-Funk backstage at the Kenworthy on April 26th with Mars Child as they celebrate the release of their debut album: Space Heater. Doors open at 10:30 and tickets will be $8. Mars Child began over fifteen years ago–created by some small town Idaho teenagers who were obsessed with the Red Hot Chili Peppers. We’re into funky jams, rockin’-and-rollin’, and connecting to our fellow humans through the noise we make. Tickets: $8 General Admission', 'https://www.kenworthy.org/wp-content/uploads/Official-Mars-Child-KPAC-Poster.pdf-232x300.jpg', 'ticketed', true
