INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Backstage Music: Plaid Raptor + Green Flannel', 'Saturday, November 18 Doors at 7:oo PM Join us BACKSTAGE for live music from PLAID RAPTOR + GREEN FLANNEL! Plaid Raptor is a genre defying band who can be categorized as progressive alternative metal funk. Green Flannel is a Punk-Rock based band with Surf, Rock, and Grunge influences. Entrance in back alley of Kenworthy Theatre. Tickets: $10 General Admission', 'https://www.kenworthy.org/wp-content/uploads/PR-GF-GIG-POSTER_LARGE_27x41_PRINT-web-198x300.jpg', 'ticketed', true
