INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Backstage Music: The Chelseas &#038; Will Fontaine', 'Friday, January 12 at 7 PM Join us for a special night of acoustic music Backstage at KPAC. THE CHELSEAS will be joined by opener WILL FONTAINE for a splendid night of music. The Chelseas are an acoustic folk band from Moscow, ID. Will Fontaine is an alternative folk rock artist from Moscow, ID. Doors will open at 6:30 PM with music starting at 7 PM. Backstage entrance is located in back alley of Kenworthy Performing Arts Centre. Tickets: $12 General Admission', 'https://www.kenworthy.org/wp-content/uploads/Chelseas-web-198x300.jpg', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Backstage Music: The Chelseas &#038; Will Fontaine');

-- Backstage Music: The Widow Cameron + Bill Tracy
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Backstage Music: The Widow Cameron + Bill Tracy', 'Friday, February 7 at 7 PM KPAC presents THE WIDOW CAMERON + BILL TRACY . Join us for two solo sets at the Kenworthy''s Backstage Speakeasy featuring two solo sets from local musicians The Widow Cameron + Bill Tracy (Mother Yeti/Desolation Horse). The show is all ages and doors open at 7 PM. The Widow Cameron is the new project of poet and songwriter Cameron McGill. Originally from Champaign, IL, he is the author of Meridians (Willow Springs Books) and In the Night Field (Augury Books) and has released seven albums, most recently 2022’s The Widow Cameron. He lives and writes and plays the piano in Moscow, Idaho. Tickets: $12', 'https://www.kenworthy.org/wp-content/uploads/Widow-Cameron-198x300.jpg', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Backstage Music: The Widow Cameron + Bill Tracy');

-- Backstage New Year&#8217;s Eve Party
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Backstage New Year&#8217;s Eve Party', 'Wednesday, December 31 at 8 PM KPAC is hosting our own New Year’s Eve Party Backstage! Featuring live music from RED CAROLINE! There will be dancing, drinks, and more. Red Caroline is a blues rock band from Boise, Idaho. The band formed in mid-2023 around longtime best friends Kaleb Muilenburg (Bass) and Jack Magnolia (Guitar) and finalized the lineup, adding Layla Booth (Vocals) Aiden Elliott (Drums), and Ayden “Goose” Booth (Keys/guitar) to complete the gang of psychedelic sorcerers. Since then, they were able to get their foot in the door locally, landing spots as support for groups like The Moss, The Velveteers, Forty Feet Tall, MX LONELY, and Boot Juice, and they released their first project, “Coastal Blues”, on February 21st, 2025. Together the band takes elements of classic garage rock, dreamy indie, and fuzzy psych, and mixes them all together to present a nostalgic sound in a new wave of sonic bliss. Tickets: $10 General Admission', 'https://www.kenworthy.org/wp-content/uploads/new-years-insta-Real-Estate-Flyer-232x300.jpg', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Backstage New Year&#8217;s Eve Party');

