-- Black History Month: Creating an Environment where Black people can Flourish and Thrive
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Black History Month: Creating an Environment where Black people can Flourish and Thrive', 'Sunday, February 4 at 7:00 PM Join us for a forum and panel discussion on Creating an Environment where Black people can Flourish and Thrive .'' This event will be facilitated by the leadership of the Idaho Black Community Alliance , Trish J. Walker and Shari Baber. They will provide Moscow business and downtown cultural leaders with strategies they can use to continue building bridges with the Black community, fostering a more inclusive and welcoming environment. Sponsored by Latah County Human Rights Task Force, Moscow Food Co-op, Moscow Human Rights Commission, University of Idaho College of Business and Economics, Colter''s Creek and Idaho Humanities Council. Tickets: Free', 'https://www.kenworthy.org/wp-content/uploads/web-listing-300x150.png', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Black History Month: Creating an Environment where Black people can Flourish and Thrive');

