-- Inland Northwest Magic: Stardust
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Inland Northwest Magic: Stardust', 'Wednesday, May 13 at 7 PM Is destiny written in the stars—or is it found inside? Step into Stardust, where sleight of hand meets storytelling in an immersive magic experience designed to delight all ages. More than a show—this is a moment of wonder you will remember long after the curtain falls. Featuring Frances Morgan, multi-award-winning magician recognized by the International Brotherhood of Magicians, Stardust invites you to witness the impossible made real through interactive illusions and captivating narrative. Presented by Inland Northwest Magic. Run Time: 1 hour 15 with 10 minute intermission Reserve your seats soon, before this opportunity fades into the night. Run Time: 1 hr 15 min | Tickets: $22 GA / $14 Student or Senior Group Rate (4+) 25% off Total', 'https://www.kenworthy.org/wp-content/uploads/INWMAGIC.STARDUST.Kenworthy.5.13.26-231x300.jpg', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Inland Northwest Magic: Stardust');

-- Innovia Foundation: Curious Conversations with Mónica Guzmán &#038; Erin Jones
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Innovia Foundation: Curious Conversations with Mónica Guzmán &#038; Erin Jones', 'Wednesday, May 31 at 6:15 PM Dynamic and well-respected authors, Mónica Guzmán and Erin Jones will share the stage to offer their perspectives on building bridges to strengthen relationships and our communities. Join us to engage in thought-provoking discussions and learn practical tools for having difficult conversations and building bridges towards a more just society. Event will be Simulcast from Bing Crosby Theater in Spokane, WA. Schedule 5:30 pm – Doors open 6:15 pm – Program begins 7:00 pm – Simulcast with Mónica and Erin Tickets: $10 Full event including food & drink ticket', 'https://www.kenworthy.org/wp-content/uploads/Untitled-design-4-1024x683-1-300x200.png', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Innovia Foundation: Curious Conversations with Mónica Guzmán &#038; Erin Jones');

-- It&#8217;s a Wonderful Life (PG)
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
