INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Moscow Film Society: Carrie (1976)', 'Wednesday, July 6 at 7 PM Moscow Film Society presents CARRIE (1976). The iconic horror masterpiece is back on the big screen again. Based on the Stephen King novel and directed by Brian De Palma, (SCARFACE, THE UNTOUCHABLES, MISSION: IMPOSSIBLE) the film has everything you could possibly want supernatural powers, high school cruelty, teen angst, religious zealots, and pig''s blood. Prom is going to be so much fun this year! Rated: R | 1 hr 38 min | Tickets: $5 General Admission', 'https://www.kenworthy.org/wp-content/uploads/carrie-poster-198x300.jpg', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Moscow Film Society: Carrie (1976)');

-- Moscow Human Rights Commission Presents: Bamboo and Barbed Wire
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Moscow Human Rights Commission Presents: Bamboo and Barbed Wire', 'Celebrate Asian American Pacific Islander Heritage Month with a screening of the documentary “Bamboo and Barbed Wire” on Friday, May 6 at 6:00 p.m. at the Kenworthy Performing Arts Theater. Bamboo and Barbed Wire examines the history of a Japanese internment camp in Idaho. Karen Day, Idaho filmmaker and director of Bamboo and Barbed Wire, and Katie Niemann, president of the Boise Valley Japanese American Citizens League, will join for a Q&A following the film screening. Sponsored by: Moscow Human Rights Commission, Associated Students at the University of Idaho, Asian American Pacific Islander Association, and the Office of Multicultural Affairs.', 'https://www.kenworthy.org/wp-content/uploads/Bamboo-and-Barbed-Wire-3.png', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Moscow Human Rights Commission Presents: Bamboo and Barbed Wire');

