-- San Francisco Scottish Fiddlers
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'San Francisco Scottish Fiddlers', 'Sunday, August 2 at 3 PM Local fiddle club musicians from Coeur d''Alene, Spokane, Troy, and Moscow areas (Mabel Vogt) join with San Francisco Bay Area musicians to bring you an extraordinary concert of Celtic joy and more. The San Francisco Scottish Fiddlers were formed in 1986 when Alasdair Fraser placed an advertisement in a local newspaper looking for people interested in sharing Scottish fiddle music. A small group of enthusiasts quickly grew to over 300 members and for this performance, over 20 musicians play under the direction of Janette Duncan. Family-friendly, this music will have you dancing in the aisles! Tickets: $25 General Admission / $10 Youth', 'https://www.kenworthy.org/wp-content/uploads/8.2.26-Kenworthy-flyer-232x300.jpg', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'San Francisco Scottish Fiddlers');

-- Second Annual Fall48 Film Festival
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Second Annual Fall48 Film Festival', 'Make a Film. Fast. Fall48 is a film challenge open to all high school students, current University of Idaho students, UI alumni, and local filmmakers in the Pacific Northwest. Teams are given 48 hours to produce an entire short film from start to finish: they write, pre-produce, shoot, and edit their original content within the assigned 48-hour window. Fall48 will host the livestream on their webpage , so tune in on the night of December 1st starting at 6:30 PM PST to see the selected and award-winning films. Please feel free to share the link with your friends and family.', 'https://www.kenworthy.org/wp-content/uploads/124170194_3558449190865480_8986929195242179915_n-300x169.jpeg', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Second Annual Fall48 Film Festival');

