-- Urban Bush Women: This Is Risk
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Urban Bush Women: This Is Risk', 'Friday, February 13 at 7:30 PM The Terry Buffington Foundation presents URBAN BUSH WOMEN: THIS IS RISK . Urban Bush Women is a groundbreaking Black women-led theatrical dance company and social activism ensemble, founded in 1984 by visionary choreographer Jawole Willa Jo Zollar as an engine and an amplifier for the unheard stories of Black Women+. UBW combines revolutionary performance, deep-healing community engagement, and ancestral knowledge from the African diaspora into a cultural force that is urgent, forward-looking, and essential. Tickets: $25 Adult / $10 Student', 'https://www.kenworthy.org/wp-content/uploads/1-4-232x300.png', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Urban Bush Women: This Is Risk');

