-- Washington Idaho Symphony ~ Voices of the East: Prokofiev &#038; Tchaikovsky
INSERT INTO public.events (title, description, poster_url, ticket_type, is_active)
SELECT 'Washington Idaho Symphony ~ Voices of the East: Prokofiev &#038; Tchaikovsky', 'Sunday, March 1 at 3 PM The Washington Idaho Symphony presents Voices of the East: Prokofiev & Tchaikovsky . Immerse yourself in the bold colors and sweeping emotion of Eastern European orchestral music in this dynamic program. The evening features violinist, and WIS Concert Master, Giselle Hillyer performing Prokofiev’s Violin Concerto No. 1 in D major, Op. 19 and Tchaikovsky’s Symphony No. 4. Together, these works celebrate the expressive power of Russian composers whose voices continue to resonate across generations. Tickets: $27 Adult / $11 Youth / Free for Children', 'https://www.kenworthy.org/wp-content/uploads/unnamed-8-194x300.webp', 'ticketed', true
WHERE NOT EXISTS (SELECT 1 FROM public.events WHERE title = 'Washington Idaho Symphony ~ Voices of the East: Prokofiev &#038; Tchaikovsky');

